// === DATA EXTRACTION ===
const rois = msg.payload.roi?.rois || [];
const blobs = msg.payload.segmentation?.blobs || [];
const classifications = msg.payload.classification?.predictions || [];
const imageUrl = msg.payload.image_url || '';
const inspTime = msg.payload.inspection_time || new Date().toISOString();

// === ALIGNMENT CHECK ===
const alignmentFound = msg.payload.alignment?.predictions?.[0]?.success === true;

const PIXEL_THRESHOLD = 250;

// === SEGMENTATION CHECK ===
const failingBlobs = blobs.filter(b => (b.pixel_count || 0) > PIXEL_THRESHOLD);
const segPass = failingBlobs.length === 0;

const segFailDetails = [];
if (!segPass) {
    const byRoi = {};
    for (const b of failingBlobs) {
        const key = b.roi_name || b.roi_id || 'Global';
        if (!byRoi[key]) {
            byRoi[key] = {
                roiName: String(key),
                classes: new Set(),
                count: 0,
                maxPixels: 0
            };
        }
        byRoi[key].classes.add(b.predicted_class || 'unknown');
        byRoi[key].count++;
        byRoi[key].maxPixels = Math.max(byRoi[key].maxPixels, b.pixel_count || 0);
    }

    for (const val of Object.values(byRoi)) {
        segFailDetails.push({
            roiName: val.roiName,
            classes: [...val.classes],
            count: val.count,
            maxPixels: val.maxPixels
        });
    }
}

// === CLASSIFICATION CHECK ===
const failingClassifications = classifications.filter(p => {
    const predictedClass = String(p.predicted_class || '').trim().toLowerCase();
    return !predictedClass.startsWith('pass');
});

const classPass = failingClassifications.length === 0;

const classFailDetails = failingClassifications.map(p => {
    const predClass = p.predicted_class || 'unknown';
    const roiId = p.roi_id;
    let roiName = p.roi_name || 'Global';

    if (roiId) {
        const matchedRoi = rois.find(r =>
            r.id === roiId ||
            r.id === Number(roiId) ||
            String(r.id) === String(roiId)
        );
        roiName = matchedRoi ? (matchedRoi.name || ('ROI ' + matchedRoi.id)) : roiName;
    }

    return { roiName, className: predClass };
});

// === FINAL PASS/FAIL ===
const pass = !(
    segPass === false ||
    classPass === false ||
    alignmentFound === false
);

// === FAIL REASONS ===
const failReasons = [];

if (alignmentFound === false) {
    failReasons.push('Alignment not found');
}

for (const sf of segFailDetails) {
    failReasons.push(
        'Seg fail in ' + sf.roiName + ': ' +
        sf.classes.join(', ') +
        ' (max ' + sf.maxPixels + 'px, threshold ' + PIXEL_THRESHOLD + 'px)'
    );
}
for (const cf of classFailDetails) {
    failReasons.push('Class fail in ' + cf.roiName + ': ' + cf.className);
}

node.warn(
    'Slave 3 - Align: ' + alignmentFound +
    ', Seg: ' + (segPass ? 'PASS' : 'FAIL') +
    ', Class: ' + (classPass ? 'PASS' : 'FAIL') +
    ', Overall: ' + (pass ? 'PASS' : 'FAIL') +
    ' | Blobs>' + PIXEL_THRESHOLD + 'px: ' + failingBlobs.length +
    ', ClassFails: ' + failingClassifications.length
);

// Output 0: final-pass-fail
const passFailMsg = { payload: pass };

// Output 1: HTTP POST to master
const MASTER_IP = '192.168.1.80';
const MASTER_PORT = 1880;
const httpMsg = {
    payload: {
        camera: 'Slave Camera 3',
        pass: pass,
        alignmentFound: alignmentFound,
        segPass: segPass,
        classPass: classPass,
        failReasons: failReasons,
        segFailDetails: segFailDetails,
        classFailDetails: classFailDetails,
        blobCount: blobs.length,
        failingBlobCount: failingBlobs.length,
        classificationCount: classifications.length,
        failingClassificationCount: failingClassifications.length,
        imageUrl: imageUrl,
        timestamp: inspTime
    },
    url: 'http://' + MASTER_IP + ':' + MASTER_PORT + '/api/slave3/results',
    method: 'POST',
    headers: { 'Content-Type': 'application/json' }
};

// Output 2: PLC write
const plcMsg = {
    payload: Buffer.from([pass ? 1 : 0])
};

return [passFailMsg, httpMsg, plcMsg];
